/*
 * A304497  Solution (a(n)) of the system of complementary equations defined
 *          in Comments.
 * https://oeis.org/A304497
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) is generated by a greedy construction. * a(0) = 1, b(0) =
 *            2, c(0) = 2*a(0)+b(0) = 4. * For each n≥0: * a(n) = least
 *            positive integer not yet used, * b(n) = least positive integer
 *            not yet used (after a(n)), * c(n) = 2*a(n)+b(n) (marked used but
 *            never considered for future a or b). * This impl...
 * Range:     u8 n <= 56, u16 n <= 60, u32 n <= 60, u64 n <= 60, u128 n <= 60,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* returns a(n) for the sequence A304497 */
seq_t a(idx_t n)
{
    /* static state */
    static seq_t *a_seq   = NULL;      /* array of a-values             */
    static size_t a_cap   = 0;          /* allocated size of a_seq       */
    static unsigned char *used = NULL;  /* boolean table of used numbers */
    static size_t used_cap = 0;         /* allocated size of used        */
    static idx_t       next    = 1;     /* smallest integer to test      */
    static idx_t       cur     = 0;     /* number of a-values generated  */

    /* ensure a_seq has room for the requested index */
    if (cur <= n) {
        if (a_cap <= (size_t)n + 1) {
            size_t new_cap = a_cap == 0 ? 1 : a_cap;
            while (new_cap <= (size_t)n) new_cap <<= 1;
            seq_t *tmp = (seq_t *)realloc(a_seq, new_cap * sizeof(seq_t));
            a_seq = tmp;
            a_cap = new_cap;
        }

        /* initialize the used table on first call */
        if (used == NULL) {
            used_cap = 1024;
            used = (unsigned char *)calloc(used_cap, sizeof(unsigned char));
        }

        /* generate a-values up to index n */
        while (cur <= n) {
            /* ---- choose a[cur] ---- */
            /* grow used array if needed before checking */
            while ((size_t)next >= used_cap) {
                size_t new_cap = used_cap;
                while (new_cap <= (size_t)next) new_cap <<= 1;
                unsigned char *tmp = (unsigned char *)realloc(used, new_cap * sizeof(unsigned char));
                used = tmp;
                for (size_t i = used_cap; i < new_cap; ++i) used[i] = 0;
                used_cap = new_cap;
            }
            while (used[next]) ++next;          /* find smallest unused */
            seq_t val_a = (seq_t)next;
            used[next] = 1;
            ++next;                              /* move to candidate for b */

            /* ---- choose b[cur] ---- */
            while ((size_t)next >= used_cap) {
                size_t new_cap = used_cap;
                while (new_cap <= (size_t)next) new_cap <<= 1;
                unsigned char *tmp = (unsigned char *)realloc(used, new_cap * sizeof(unsigned char));
                used = tmp;
                for (size_t i = used_cap; i < new_cap; ++i) used[i] = 0;
                used_cap = new_cap;
            }
            while (used[next]) ++next;          /* find next unused */
            seq_t val_b = (seq_t)next;
            used[next] = 1;
            ++next;                              /* next will be used for next iteration */

            /* ---- compute c[cur] (mark as used) ---- */
            seq_t val_c = val_a * (seq_t)2 + val_b;
            idx_t idx_c = (idx_t)val_c;
            if ((size_t)idx_c >= used_cap) {
                size_t new_cap = used_cap;
                while (new_cap <= (size_t)idx_c) new_cap <<= 1;
                unsigned char *tmp = (unsigned char *)realloc(used, new_cap * sizeof(unsigned char));
                used = tmp;
                for (size_t i = used_cap; i < new_cap; ++i) used[i] = 0;
                used_cap = new_cap;
            }
            used[idx_c] = 1;

            /* store the a-value */
            a_seq[(size_t)cur] = val_a;
            ++cur;
        }
    }
    return a_seq[(size_t)n];
}
